begin;
select set_config('test.host',gen_random_uuid()::text,true),set_config('test.attendee',gen_random_uuid()::text,true),set_config('test.outsider',gen_random_uuid()::text,true),set_config('test.registered',gen_random_uuid()::text,true);
insert into auth.users(id,aud,role,is_anonymous,raw_user_meta_data,created_at,updated_at) select current_setting('test.'||v)::uuid,'authenticated','authenticated',v<>'registered',jsonb_build_object('full_name','Rollback '||v),now(),now() from(values('host'),('attendee'),('outsider'),('registered')) s(v);
set local role authenticated;
do $$
declare h uuid:=current_setting('test.host')::uuid; a uuid:=current_setting('test.attendee')::uuid; o uuid:=current_setting('test.outsider')::uuid; reg uuid:=current_setting('test.registered')::uuid; r jsonb; item jsonb; s jsonb; rid uuid; iid uuid; aid uuid; cid uuid; slug text; key_before text; key_after text; proof text; n integer;
begin
 perform set_config('request.jwt.claim.sub',h::text,true);
 r:=public.retro_command('create','{"name":"Rollback host","title":"Authorization tests","duration":5}'::jsonb); slug:=r->>'slug';rid:=(r->>'id')::uuid;
 select host_key into strict key_before from public.retro_host_keys where retro_id=rid;
 item:=public.retro_command('item_save',jsonb_build_object('slug',slug,'kind','reflection','title','Original reflection'));iid:=(item->>'id')::uuid;
 item:=public.retro_command('item_save',jsonb_build_object('slug',slug,'kind','action','title','Host-only action'));aid:=(item->>'id')::uuid;
 perform public.retro_command('item_save',jsonb_build_object('slug',slug,'id',iid,'version',1,'title','Updated reflection','description','Persistent description'));
 perform set_config('request.jwt.claim.sub',a::text,true);
 if public.retro_snapshot(slug) is not null then raise exception 'Nonmember read was allowed'; end if;
 perform public.retro_command('join',jsonb_build_object('slug',slug,'name','Rollback attendee'));
 select count(*) into n from public.retro_host_keys where retro_id=rid;if n<>0 then raise exception 'Host key leaked';end if;
 s:=public.retro_snapshot(slug);if jsonb_array_length(s->'items')<>2 then raise exception 'Attendee cannot see actions';end if;
 begin perform public.retro_command('item_save',jsonb_build_object('slug',slug,'kind','action','title','Forbidden action'));raise exception 'Expected host-only create failure';exception when insufficient_privilege then null;end;
 begin perform public.retro_command('item_save',jsonb_build_object('slug',slug,'id',aid,'version',1,'title','Forbidden update'));raise exception 'Expected host-only edit failure';exception when insufficient_privilege then null;end;
 begin perform public.retro_command('item_vote',jsonb_build_object('slug',slug,'item_id',aid,'active',true));raise exception 'Expected readonly action failure';exception when insufficient_privilege then null;end;
 begin perform public.retro_command('item_delete',jsonb_build_object('slug',slug,'item_id',iid));raise exception 'Expected author check';exception when insufficient_privilege then null;end;
 perform public.retro_command('item_vote',jsonb_build_object('slug',slug,'item_id',iid,'active',true));perform public.retro_command('item_vote',jsonb_build_object('slug',slug,'item_id',iid,'active',true));
 select count(*) into n from public.item_votes where item_id=iid;if n<>1 then raise exception 'Duplicate vote';end if;
 item:=public.retro_command('comment_save',jsonb_build_object('slug',slug,'item_id',iid,'body','Timestamped comment'));cid:=(item->>'id')::uuid;
 perform public.retro_command('comment_vote',jsonb_build_object('slug',slug,'comment_id',cid,'active',true));perform public.retro_command('comment_vote',jsonb_build_object('slug',slug,'comment_id',cid,'active',false));
 select count(*) into n from public.comment_votes where comment_id=cid;if n<>0 then raise exception 'Comment unvote failed';end if;
 begin perform public.retro_command('claim_host',jsonb_build_object('slug',slug,'key','wrong'));raise exception 'Expected invalid key failure';exception when insufficient_privilege then null;end;
 perform public.retro_command('claim_host',jsonb_build_object('slug',slug,'key',key_before));
 select host_key into strict key_after from public.retro_host_keys where retro_id=rid;if key_after=key_before then raise exception 'Host key did not rotate';end if;
 perform public.retro_command('item_save',jsonb_build_object('slug',slug,'id',aid,'version',1,'title','New host action update'));
 perform public.retro_command('settings',jsonb_build_object('slug',slug,'extend',5,'allow_guests',false));
 perform set_config('request.jwt.claim.sub',h::text,true);
 select count(*) into n from public.retro_host_keys where retro_id=rid;if n<>0 then raise exception 'Former host still sees key';end if;
 begin perform public.retro_command('claim_host',jsonb_build_object('slug',slug,'key',key_before));raise exception 'Stale key reused';exception when insufficient_privilege then null;end;
 begin perform public.retro_command('item_save',jsonb_build_object('slug',slug,'id',iid,'version',1,'title','Stale title'));raise exception 'Expected version conflict';exception when serialization_failure then null;end;
 begin insert into public.retro_items(retro_id,author_id,kind,title) values(rid,h,'reflection','Direct bypass');raise exception 'Expected direct write denied';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',o::text,true);
 begin perform public.retro_command('join',jsonb_build_object('slug',slug,'name','Rollback outsider'));raise exception 'Guest-disabled join allowed';exception when insufficient_privilege then null;end;
 if public.retro_snapshot(slug) is not null then raise exception 'Cross-retro read';end if;
 perform set_config('request.jwt.claim.sub',h::text,true);proof:=public.retro_command('prepare_guest_merge')->>'token';
 perform set_config('request.jwt.claim.sub',reg::text,true);perform public.retro_command('merge_guest',jsonb_build_object('token',proof));
 if public.retro_snapshot(slug) is null then raise exception 'Guest history not merged';end if;
 select count(*) into n from public.retro_items where id=iid and author_id=reg;if n<>1 then raise exception 'Activity ownership not merged';end if;
 perform set_config('request.jwt.claim.sub',h::text,true);if public.retro_snapshot(slug) is not null then raise exception 'Old guest retains access after merge';end if;
 perform set_config('test.passed','true',true);
end $$;
select current_setting('test.passed') as authorization_checks_passed;
rollback;
